// ---------- estrategias de enseñanza y evaluativas (celdas de la tabla de temas) ----------
// Todo sale literal del Syllabus. La celda de enseñanza trae una "Metodología Activa de Aprendizaje" y una lista
// de "Técnicas Pedagógicas", cada una con su "Propósito y Aplicación". La celda evaluativa trae las evaluaciones
// formativas y la sumativa, cada una con Estrategia, Mecanismo y Descripción (Ind-xx).

// Parte un bloque en elementos de lista: "- Algo. - Otro" (con o sin espacio tras el guion).
const PARTIR_LISTA = /(?:^|\s)-\s+(?=[A-ZÁÉÍÓÚÑ¿¡])|(?<=[.:;)])-\s*(?=[A-ZÁÉÍÓÚÑ])/;
const sinPuntoFinal = s => String(s || '').replace(/[\s.;:,]+$/, '').trim();

function parsearEnsenanza(raw) {
  const t = aplanar(raw);
  const vacio = { metodologias: [], tecnicas: [] };
  if (!t) return vacio;
  const iMet = t.search(/Metodolog[ií]as?\s+Activas?\s+de\s+Aprendizaje\s*:?/i);
  const iTec = t.search(/T[eé]cnicas?\s+Pedag[oó]gicas?\s*:?/i);
  const bloqueMet = iMet < 0 ? '' : t.slice(iMet, iTec > iMet ? iTec : undefined).replace(/^Metodolog[ií]as?\s+Activas?\s+de\s+Aprendizaje\s*:?\s*/i, '');
  const bloqueTec = iTec < 0 ? '' : t.slice(iTec, iMet > iTec ? iMet : undefined).replace(/^T[eé]cnicas?\s+Pedag[oó]gicas?\s*:?\s*/i, '');

  const metodologias = bloqueMet.split(PARTIR_LISTA).map(x => x.trim()).filter(Boolean).map(x => {
    const i = x.indexOf(':');
    const nombre = i > 0 && i <= 120 ? x.slice(0, i) : x.split(/\s+/).slice(0, 8).join(' ');
    return { nombre: sinPuntoFinal(nombre), descripcion: i > 0 && i <= 120 ? x.slice(i + 1).trim() : x };
  });

  const tecnicas = bloqueTec.split(PARTIR_LISTA).map(x => x.trim()).filter(Boolean).map(x => {
    const m = /Prop[oó]sito\s+y\s+Aplicaci[oó]n\s*:?/i.exec(x);
    if (m) return { nombre: sinPuntoFinal(x.slice(0, m.index)), proposito: x.slice(m.index + m[0].length).trim() };
    const corte = x.search(/[.:]/);
    return corte > 0 ? { nombre: sinPuntoFinal(x.slice(0, corte)), proposito: x.slice(corte + 1).trim() } : { nombre: sinPuntoFinal(x), proposito: '' };
  }).filter(x => x.nombre);

  return { metodologias, tecnicas };
}

function parsearEvaluativas(raw) {
  const t = aplanar(raw);
  const out = { formativas: [], sumativas: [] };
  if (!t) return out;
  const re = /Evaluaci[oó]n(?:es)?\s+(formativa|sumativa)s?\s*[.:]?/gi;
  const cortes = [];
  let m;
  while ((m = re.exec(t))) cortes.push({ tipo: m[1].toLowerCase(), ini: m.index, fin: re.lastIndex });
  cortes.forEach((c, i) => {
    const cuerpo = t.slice(c.fin, i + 1 < cortes.length ? cortes[i + 1].ini : undefined);
    const entradas = cuerpo.split(/-?\s*(?=Estrategia\s*:)/i).map(x => x.trim()).filter(x => /^Estrategia\s*:/i.test(x));
    for (const e of entradas) {
      const g = /^Estrategia\s*:\s*([\s\S]*?)\s*Mecanismo\s*:\s*([\s\S]*?)\s*Descripci[oó]n\s*:\s*([\s\S]*)$/i.exec(e);
      if (!g) { out[c.tipo === 'formativa' ? 'formativas' : 'sumativas'].push({ estrategia: sinPuntoFinal(e.replace(/^Estrategia\s*:\s*/i, '')), mecanismo: '', descripcion: '', indicadores: [] }); continue; }
      const descripcion = g[3].replace(/\s*-\s*$/, '').trim();
      const indicadores = [...new Set((descripcion.match(/Ind-\d+/gi) || []).map(x => 'Ind-' + x.slice(4)))];
      out[c.tipo === 'formativa' ? 'formativas' : 'sumativas'].push({
        estrategia: sinPuntoFinal(g[1]), mecanismo: sinPuntoFinal(g[2]), descripcion, indicadores
      });
    }
  });
  return out;
}

// ---------- unidades ----------

const unidades = [];

// Cada unidad empieza en la fila cuya primera celda dice "Unidad Nro. N" (o "Unidad N°", "Unidad No.").
// Word une en una sola tabla las tablas que quedan pegadas, así que se corta por esas filas y no por tabla.
const RE_UNIDAD = /^Unidad\s*(?:Nro\.?|N[°ºo]\.?|N[uú]mero)\s*(\d+)|^Unidad\s+(\d+)\s*$/i;
const tablasUnidad = [];
for (const filas of tablas) {
  let enCurso = null;
  for (const fila of filas) {
    if (RE_UNIDAD.test(aplanar(fila[0]))) tablasUnidad.push(enCurso = [fila]);
    else if (enCurso) enCurso.push(fila);
  }
}

for (const filas of tablasUnidad) {
  const m = RE_UNIDAD.exec(aplanar(filas[0][0]));
  const numero = Number(m[1] || m[2]);
  if (unidades.some(u => u.numero === numero)) continue;
  const nombre = aplanar(filas[0][1]);
  const horas = aplanar(filas[0][3]);

  const filaInd = filas.find(c => norm(c[0]).startsWith('indicadores de logro'));
  const indicadoresRaw = filaInd ? aplanar(filaInd[1]) : '';
  const indicadores = indicadoresRaw
    .split(/(?=Indicador de Logro\s*\d+\s*:)/gi)
    .map(x => x.trim())
    .filter(Boolean);

  const iCabecera = filas.findIndex(
    c => norm(c[0]) === 'temas'
  );
  const iBiblio = filas.findIndex(c => norm(c[0]).startsWith('bibliografia'));
  const fin = iBiblio === -1 ? filas.length : iBiblio;

  const temas = [];
  let actual = null;
  let estrategias_ensenanza = '';
  let estrategias_evaluativas = '';
  const celdasEns = [];
  const celdasEval = [];

  for (let i = iCabecera + 1; i < fin; i++) {
    const c = filas[i];
    if (!c) continue;
    if ((norm(c[2]) === 'ad' && norm(c[3]) === 'ei') || (norm(c[0]) === 'ad' && norm(c[1]) === 'ei')) continue; // subcabecera AD/EI
    const subtema = aplanar(c[1]);
    if (!subtema) continue;

    const nombreTema = aplanar(c[0]);
    if (nombreTema || !actual) {
      actual = { nombre: nombreTema, subtemas: [] };
      temas.push(actual);
    }
    actual.subtemas.push({
      nombre: subtema,
      horas_trabajo_directo: aplanar(c[2]),
      horas_trabajo_independiente: aplanar(c[3])
    });
    if (!estrategias_ensenanza && (c[4] || '').trim()) estrategias_ensenanza = c[4].trim();
    if (!estrategias_evaluativas && (c[5] || '').trim()) estrategias_evaluativas = c[5].trim();
    if ((c[4] || '').trim()) celdasEns.push({ tema: actual, raw: c[4].trim() });
    if ((c[5] || '').trim()) celdasEval.push({ raw: c[5].trim() });
  }

  // La celda de enseñanza suele estar combinada para toda la unidad; si cada tema trae la suya, cada tema usa la propia.
  const ensenanza = parsearEnsenanza(estrategias_ensenanza);
  if (new Set(celdasEns.map(x => aplanar(x.raw))).size > 1) celdasEns.forEach(x => { x.tema.ensenanza = parsearEnsenanza(x.raw); });
  const evalPars = celdasEval.map(x => parsearEvaluativas(x.raw));
  const evaluacion_syllabus = { formativas: evalPars.flatMap(x => x.formativas), sumativas: evalPars.flatMap(x => x.sumativas) };

  function bibliografiaTras(prefijo, letra) {
    const i = filas.findIndex(c => norm(c[0]).startsWith(norm(prefijo)));
    if (i === -1) return { raw: '', entradas: [] };
    // El texto puede estar en la misma fila (segunda celda) o en la siguiente.
    const raw = ((filas[i][1] || '').trim() || (filas[i + 1] ? (filas[i + 1][0] || '').trim() : ''));
    const entradas = splitRefs(raw).map((t, k) =>
      entradaBibliografica(t, 'U' + numero + '-' + letra + (k + 1), letra === 'B' ? 'basica' : 'complementaria')
    );
    return { raw: aplanar(raw), entradas };
  }

  unidades.push({
    numero,
    nombre,
    horas_estimadas: horas,
    indicadores_logro: indicadores,
    indicadores_logro_raw: indicadoresRaw,
    temas,
    estrategias_ensenanza,
    estrategias_evaluativas,
    ensenanza,
    evaluacion_syllabus,
    bibliografia: {
      basica: bibliografiaTras('Bibliografía básica', 'B'),
      complementaria: bibliografiaTras('Bibliografía complementaria', 'C')
    }
  });
}

if (unidades.length === 0) {
  throw new Error(
    'No se encontró ninguna unidad ("Unidad Nro. N") en el documento. ' +
