  }

  return {
    json: {
      ...j,
      marcadores,
      advertencias,
      plantilla: {
        estado: 'cotejada',
        url: urlPlantilla,
        total_marcadores: enPlantilla.length,
        sin_valor: sinValor,
        sin_uso: sinUso
      }
    }
  };
});

