// 3 → 1,1,2,2,3,3 · 4 → 1,1,2,2,3,4 · 5 → 1,1,2,3,4,5 · 6 → uno por recurso · 7 o más → algún recurso agrupa dos.
function coberturaRecursos(n) {
  const fijas = { 1: [0, 0, 0, 0, 0, 0], 2: [0, 0, 1, 1, 1, 1], 3: [0, 0, 1, 1, 2, 2], 4: [0, 0, 1, 1, 2, 3], 5: [0, 0, 1, 2, 3, 4] };
  if (n < 1) return ORDEN.map(() => []);
  if (fijas[n]) return fijas[n].map(i => [i]);
  return ORDEN.map((_, k) => {
    const desde = Math.floor(k * n / ORDEN.length);
