const limpio = s => String(s || '').replace(/\s+/g, ' ').trim();
const minus = s => { const t = limpio(s); return t.length > 1 && t !== t.toUpperCase() ? t.charAt(0).toLocaleLowerCase('es') + t.slice(1) : t; };
// Metodologías activas del nivel (con prioridad): de aquí salen las que completan una metodología distinta por tema.
const MET_NIVEL = {"Licenciatura":[["Aprendizaje Basado en Evidencias","P"],["Aprendizaje Basado en Problemas (ABP)","P"],["Aprendizaje Basado en Juegos (Gamificación-Ludificación)","C"],["Aprendizaje Basado en Estudios de Caso (ABC)","P"],["Aprendizaje por Observación","P"],["Método de Casos","P"],["Aprendizaje Adaptativo","P"],["Aprendizaje Basado en Pensamiento","P"],["Aprendizaje Basado en Proyectos","P"],["Aprendizaje Basado en Retos","P"],["Aprendizaje Colaborativo","C"],["Aprendizaje por Descubrimiento","P"],["Aprendizaje por Simulación","P"],["Aula Invertida","P"],["Pensamiento de Diseño en el Aprendizaje","P"],["Aprendizaje Colaborativo Internacional en Línea","C"],["Aprendizaje Experimental","P"]],"Especialización":[["Aprendizaje Basado en Evidencias","P"],["Aprendizaje Basado en Problemas (ABP)","P"],["Aprendizaje Basado en Estudios de Caso (ABC)","P"],["Aprendizaje por Observación","C"],["Método de Casos","P"],["Aprendizaje Adaptativo","C"],["Aprendizaje Basado en Pensamiento","C"],["Aprendizaje Basado en Proyectos","P"],["Aprendizaje Basado en Retos","P"],["Aprendizaje Colaborativo","C"],["Aprendizaje por Descubrimiento","C"],["Aprendizaje por Simulación","P"],["Aula Invertida","P"],["Pensamiento de Diseño en el Aprendizaje","P"],["Aprendizaje Colaborativo Internacional en Línea","C"],["Aprendizaje Experimental","C"]],"Doctorado":[["Aprendizaje Basado en Evidencias","P"],["Aprendizaje Basado en Problemas (ABP)","P"],["Aprendizaje Basado en Estudios de Caso (ABC)","P"],["Aprendizaje por Observación","C"],["Método de Casos","P"],["Aprendizaje Basado en Pensamiento","C"],["Aprendizaje Basado en Proyectos","P"],["Aprendizaje Basado en Retos","P"],["Aprendizaje por Descubrimiento","C"],["Aprendizaje por Simulación","P"],["Aula Invertida","P"],["Pensamiento de Diseño en el Aprendizaje","P"],["Aprendizaje Colaborativo Internacional en Línea","C"],["Aprendizaje Experimental","C"]],"Tecnológico":[["Aprendizaje Basado en Evidencias","C"],["Aprendizaje Basado en Problemas (ABP)","P"],["Aprendizaje Basado en Juegos (Gamificación-Ludificación)","P"],["Aprendizaje Basado en Estudios de Caso (ABC)","P"],["Aprendizaje por Observación","P"],["Método de Casos","C"],["Aprendizaje Adaptativo","P"],["Aprendizaje Basado en Pensamiento","P"],["Aprendizaje Basado en Proyectos","P"],["Aprendizaje Basado en Retos","P"],["Aprendizaje Colaborativo","C"],["Aprendizaje por Descubrimiento","P"],["Aprendizaje por Simulación","P"],["Aula Invertida","C"],["Pensamiento de Diseño en el Aprendizaje","C"],["Aprendizaje Experimental","P"]]};
const usoMet = new Map(); // veces que se usó cada una; el conteo vale para todas las unidades de la petición
const nivelDeTexto = v => { const n = norm(v); if (/doctor/.test(n)) return 'Doctorado'; if (/especial/.test(n)) return 'Especialización'; if (/tecnol|tecnic/.test(n)) return 'Tecnológico'; return 'Licenciatura'; };
const AFINIDAD_MET = [[/simulaci/, /simul|escenario|decision|emergenc|crisis/], [/caso/, /caso|situacion|incidente/], [/proyecto/, /proyecto|plan|dise|program/], [/retos/, /reto|desaf|competenc/], [/problemas|abp/, /problema|riesgo|prevenc|causa/], [/evidencias/, /evidenc|valoraci|evaluaci|medici|resultado/], [/observacion/, /observ|identific|reconoc|analisis/], [/juegos/, /juego|motivaci|habito/], [/descubrimiento/, /explor|descubr|concepto|fundamento/], [/aula invertida/, /fundamento|concepto|teori/], [/colaborativo/, /equipo|comunidad|colabor|particip/], [/pensamiento de dise/, /dise|innov|propuesta/], [/adaptativo/, /nivel|ritmo|individual/], [/experimental/, /experiment|prueba|laborator/]];
const sinCursiva = s => String(s || '').replace(/\*/g, '').trim();

// Puntaje de una página: apariciones de las palabras del tema/subtema (cada palabra cuenta hasta 3 veces).
function puntaje(textoNorm, palabras) {
  let p = 0;
  for (const w of palabras) {
    let n = 0, i = textoNorm.indexOf(w);
    while (i !== -1 && n < 3) { n++; i = textoNorm.indexOf(w, i + w.length); }
    p += n;
  }
  return p;
}

// Prepara una sola vez el texto normalizado de cada página.
const fuentes = paquete.fuentes.map(f => ({
