  }
  const PLANTILLAS = [
    [/aula invertida/, (T, S) => 'Antes de cada sesión del ' + T + ', el estudiante estudia por su cuenta los contenidos de ' + S + '; el tiempo de clase se dedica a aplicarlos, discutirlos y resolver dudas con el docente.'],
