  const explicar = (n, T, S) => { const k = norm(n); const p = PLANTILLAS.find(([rx]) => rx.test(k)); return p ? p[1](T, S) : 'En el ' + T + ', se aplica en ' + S + '.'; };
  const enLista = a => (a.length > 1 ? a.slice(0, -1).join(', ') + ' y ' + a[a.length - 1] : a.join(''));
