  if ((ensenanza.metodologias || []).length || delCatalogo.length) {
    let propias = 0;
    temas.forEach((t, ti) => {
      if (t.ensenanza && (t.ensenanza.metodologias || []).length) { propias++; return; }
      const nombreTema = limpio(t.nombre).replace(/^\d+\s*[.)\-–]?\s*/, '');
